    //
    TwistExpander_Arcturus_Arx::KEY_A_C_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Arcturus_Arx::KEY_A_C_B(PARAMS_SEED);

    KeyDiffuse_A_A_C(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Arcturus_Arx::KEY_A_C_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Arcturus_Arx::KEY_A_C_D(PARAMS_SEED);

    KeyDiffuse_B_A_C(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Arcturus_Arx::KEY_A_C_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(ARCTURUS_KEY_A_C_IceLaneA, ARCTURUS_KEY_A_C_IceLaneB, ARCTURUS_KEY_A_C_IceLaneC, ARCTURUS_KEY_A_C_IceLaneD, &(pWorkSpace->mKeyBoxA[2U][0]));

