    // dst: [$arcane]
    //
    TwistExpander_Arcturus_Arx::KEY_A_D_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Arcturus_Arx::KEY_A_D_B(PARAMS_SEED);

    KeyDiffuse_A_A_D(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Arcturus_Arx::KEY_A_D_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Arcturus_Arx::KEY_A_D_D(PARAMS_SEED);

    KeyDiffuse_B_A_D(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Arcturus_Arx::KEY_A_D_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(ARCTURUS_KEY_A_D_IceLaneA, ARCTURUS_KEY_A_D_IceLaneB, ARCTURUS_KEY_A_D_IceLaneC, ARCTURUS_KEY_A_D_IceLaneD, &(pWorkSpace->mKeyBoxA[3U][0]));

    // Key flow — A / E

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Arcturus_Arx::KEY_A_E_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
